// Table views and CSV downloads in the report runtime carry the chart's own rows (DEL-16,
// FEA-CH-45, FEA-CH-48, TYP-36). Every chart type is generated by the release CLI from one
// fixture and read at desktop and phone widths. Checked for each:
// - Header: the fields the chart references plus `encoding.detail`, in source column order:
//   the CSV header, or the inline rows' key order (TYP-25).
// - Text: shown as written, and markup in a cell is never parsed.
// - Booleans and numbers: booleans print as written, and numbers appear at the author's precision.
// - CSV: the Table's columns and rows, with standard quoting and UTF-8.
// - Pages: long tables show 1,000 rows at a time, with a count of all and shown.
// - Facets: a faceted chart has one Table and one CSV, with the facet column.
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { harness, watchErrors } from './browser-harness.mjs';
import { figureDownload } from './chart-interaction-checks.mjs';
import { reports, settle } from './report-runtime.mjs';

const fence = value => `\n\`\`\`chart\n${JSON.stringify(value)}\n\`\`\`\n`;
const INJECTION = '<img id="source-injection" src=x onerror="window.__bad=true">';
// Source column order: x, c, y, note, flag, empty, late<key>, unused. `unused` is referenced by nothing.
const rows = [
  { x: 1, c: 'P', y: 1.23456789, note: 'plain', flag: true, empty: '', 'late<key>': 'first', unused: 'never shipped' },
  { x: 2, c: 'Q', y: 3, note: 'line 1,\nline "2", Ž', flag: false, empty: '', 'late<key>': INJECTION, unused: 'never shipped' },
];
const detail = ['note', 'flag', 'empty', 'late<key>'];
const CHARTS = [
  ['line', { x: 'x', y: 'y' }],
  ['area', { x: 'x', y: 'y' }],
  ['bar', { x: 'c', y: 'y' }],
  ['scatter', { x: 'x', y: 'y' }],
  ['pie', { x: 'c', y: 'y' }],
  ['heatmap', { x: 'c', y: 'note', color: 'y' }],
  ['histogram', { x: 'y' }],
  ['boxplot', { x: 'c', y: 'y' }],
];
const order = Object.keys(rows[0]);
/** The embedded columns TYP-36 names, in source column order. */
const expectedColumns = encoding => {
  const used = new Set([...Object.values(encoding), ...detail]);
  return order.filter(key => used.has(key));
};
const quote = v => (/[",\r\n]/.test(String(v)) ? `"${String(v).replaceAll('"', '""')}"` : String(v));
const toCsv = list => `${Object.keys(list[0]).map(quote).join(',')}\r\n${list.map(r => Object.values(r).map(quote).join(',')).join('\r\n')}\r\n`;
const long = Array.from({ length: 1010 }, (_, i) => (i === 1009 ? { value: i, late: 'Last source field' } : { value: i }));
const facetRows = [
  { f: 'Left', x: 'a', y: 2 },
  { f: 'Left', x: 'b', y: 3 },
  { f: 'Right', x: 'a', y: 4 },
];

// Every chart type twice: from a CSV file and from inline rows.
const SOURCES = [['csv', { csv: 'data/records.csv' }], ['inline', { inline: rows }]];
const source = '---\ntitle: Source tables\nversion: "1"\n---\n\nTables and CSV of every chart type.\n'
  + SOURCES.flatMap(([form, data]) => CHARTS.map(([type, encoding]) => fence({ type, title: `Complete ${type} records from ${form}`, encoding: { ...encoding, detail }, data }))).join('')
  + fence({ type: 'histogram', title: 'A long source', encoding: { x: 'value', detail: ['late'] }, data: { inline: long } })
  + fence({ type: 'bar', title: 'Panels', encoding: { x: 'x', y: 'y', facet: 'f' }, data: { csv: 'data/panels.csv' } });
const files = { 'data/records.csv': toCsv(rows), 'data/panels.csv': toCsv(facetRows) };

const h = await harness('source-tables');
const inputs = await reports(h.dir, { only: [], extra: { tables: source }, files: { tables: files } });
const cases = [];
const errors = [];
const failures = [];
const check = async (label, fn) => {
  try {
    await fn();
    cases.push(label);
  } catch (error) {
    failures.push(`${label}: ${error.message}`);
  }
};

/** Parse RFC 4180 CSV text into rows of fields. */
function parseCsv(text) {
  const out = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (quoted) {
      if (ch === '"' && text[i + 1] === '"') { field += '"'; i++; } else if (ch === '"') quoted = false; else field += ch;
    } else if (ch === '"') quoted = true;
    else if (ch === ',') { row.push(field); field = ''; } else if (ch === '\r' && text[i + 1] === '\n') { row.push(field); out.push(row); row = []; field = ''; i++; } else field += ch;
  }
  if (field || row.length) { row.push(field); out.push(row); }
  return out;
}

const tableOf = figure => figure.locator('.rv-chart__table').evaluate(wrap => ({
  status: wrap.querySelector('.rv-chart__table-status')?.textContent ?? null,
  header: [...wrap.querySelectorAll('thead th')].map(th => th.textContent),
  rows: [...wrap.querySelectorAll('tbody tr')].map(tr => [...tr.querySelectorAll('td')].map(td => td.textContent)),
  markup: wrap.querySelectorAll('tbody td *').length,
}));
/** The figure's CSV download; a missing download reads as an empty file so its checks fail. */
const download = async (page, figure) => {
  try {
    const file = await figureDownload(page, figure, 'csv', { timeout: 10_000 });
    return { name: file.suggestedFilename(), text: readFileSync(await file.path(), 'utf8') };
  } catch (error) {
    failures.push(`${await figure.locator('.rv-chart__title').textContent()}: no CSV download (${error.message.split('\n')[0]})`);
    return { name: '', text: '' };
  }
};
const payloadOf = figure => figure.locator('script[data-rv-payload]').evaluate(node => JSON.parse(node.textContent));

// Chromium drops every eleventh download a page starts in quick succession, so each page load
// downloads at most nine files: the CSV-source charts with the panels, then the inline charts with
// the long source.
try {
  for (const width of [1280, 390]) {
    for (const part of ['csv', 'inline']) {
      const page = await h.browser.newPage({ viewport: { width, height: 900 }, reducedMotion: 'reduce', acceptDownloads: true });
      watchErrors(page, errors);
      await page.goto(`${inputs.base}/tables/report.html`);
      await settle(page);
      const figures = page.locator('figure[data-rv-chart]');
      await check(`${part} @${width}: one figure per chart`, async () => assert.equal(await figures.count(), 2 * CHARTS.length + 2));

      for (const [i, [form, type, encoding]] of SOURCES.flatMap(([form]) => CHARTS.map(c => [form, ...c])).entries()) {
        if (form !== part) continue;
        const at = `${type} from ${form} @${width}`;
        const figure = figures.nth(i);
        const payload = await payloadOf(figure);
        const expected = expectedColumns(encoding);
        const same = actual => assert.deepEqual(actual, expected);
        await check(`${at}: the payload embeds the referenced fields and encoding.detail in source order`, () => same(payload.columns));
        await figure.locator('.rv-chart__action--table').click();
        const table = await tableOf(figure);
        const columns = table.header;
        await check(`${at}: Table header`, () => same(columns));
        await check(`${at}: Table lists every row`, () => assert.equal(table.rows.length, rows.length));
        await check(`${at}: Table status`, () => assert.equal(table.status, '2 observations; 2 shown'));
        const cell = (r, key) => table.rows[r]?.[columns.indexOf(key)];
        await check(`${at}: text as written, newline and quotes kept`, () => assert.equal(cell(1, 'note'), rows[1].note));
        await check(`${at}: an empty cell stays empty`, () => assert.deepEqual([cell(0, 'empty'), cell(1, 'empty')], ['', '']));
        await check(`${at}: booleans as written`, () => assert.deepEqual([cell(0, 'flag'), cell(1, 'flag')], ['true', 'false']));
        await check(`${at}: markup is text, never parsed`, async () => {
          assert.equal(cell(1, 'late<key>'), INJECTION);
          assert.equal(table.markup, 0);
          assert.equal(await page.evaluate(() => [document.getElementById('source-injection'), window.__bad ?? null]).then(v => v.every(x => x === null)), true);
        });
        await check(`${at}: numbers at the author's precision`, () => assert.equal(cell(0, 'y'), '1.23'));
        const csv = await download(page, figure);
        const parsed = parseCsv(csv.text);
        await check(`${at}: CSV header is the Table's`, () => assert.deepEqual(parsed[0], columns));
        await check(`${at}: CSV rows`, () => assert.equal(parsed.length - 1, rows.length));
        await check(`${at}: CSV keeps quotes, newline and UTF-8`, () => assert.equal(parsed[2][columns.indexOf('note')], rows[1].note));
        await check(`${at}: CSV records end in CRLF`, () => {
          // Outside quoted fields every line break is CRLF; inside them the author's newline stays.
          const unquoted = csv.text.split('"').filter((_, k) => k % 2 === 0).join('');
          assert.ok(csv.text.endsWith('\r\n'));
          assert.equal(unquoted.replaceAll('\r\n', '').includes('\n'), false);
        });
        await check(`${at}: CSV numbers at the author's precision`, () => assert.equal(parsed[1][columns.indexOf('y')], '1.23'));
        await check(`${at}: CSV empty cell stays empty`, () => assert.equal(parsed[2][columns.indexOf('empty')], ''));
        await check(`${at}: CSV booleans as written`, () => assert.deepEqual([parsed[1][columns.indexOf('flag')], parsed[2][columns.indexOf('flag')]], ['true', 'false']));
        await check(`${at}: CSV file named after the title`, () => assert.match(csv.name, new RegExp(`complete-${type}-records-from-${form}.*\\.csv$`, 'i')));
        await figure.locator('.rv-chart__action--table').click();
      }

      // 1,010 rows: 1,000 at a time, every row in the CSV, the late field kept.
      if (part === 'inline') {
        const at = `long @${width}`;
        const figure = figures.nth(2 * CHARTS.length);
        await figure.locator('.rv-chart__action--table').click();
        let table = await tableOf(figure);
        await check(`${at}: header`, () => assert.deepEqual(table.header, ['value', 'late']));
        await check(`${at}: first page`, () => assert.deepEqual([table.rows.length, table.status], [1000, '1010 observations; 1000 shown']));
        await figure.getByRole('button', { name: 'Show 1,000 more observations' }).click();
        table = await tableOf(figure);
        await check(`${at}: second page`, () => assert.deepEqual([table.rows.length, table.status], [1010, '1010 observations; 1010 shown']));
        await check(`${at}: the last row keeps its late field`, () => assert.deepEqual(table.rows.at(-1), ['1,009', 'Last source field']));
        const parsed = parseCsv((await download(page, figure)).text);
        await check(`${at}: the CSV has every row`, () => assert.equal(parsed.length, 1011));
        await check(`${at}: the CSV's last row`, () => assert.deepEqual(parsed.at(-1), ['1009', 'Last source field']));
        await figure.locator('.rv-chart__action--table').click();
      }

      // A faceted chart: one Table and one CSV for the figure, with the facet column.
      if (part === 'csv') {
        const at = `facets @${width}`;
        const figure = figures.nth(2 * CHARTS.length + 1);
        await check(`${at}: one Table and one CSV action`, async () => assert.deepEqual(
          [await figure.locator('.rv-chart__action--table').count(), await figure.locator('.rv-chart__action--csv').count()], [1, 1]));
        await figure.locator('.rv-chart__action--table').click();
        const table = await tableOf(figure);
        await check(`${at}: every panel's rows with the facet column`, () => {
          assert.deepEqual(table.header, ['f', 'x', 'y']);
          assert.deepEqual(table.rows, [['Left', 'a', '2'], ['Left', 'b', '3'], ['Right', 'a', '4']]);
        });
        const parsed = parseCsv((await download(page, figure)).text);
        await check(`${at}: one CSV for the figure`, () => assert.deepEqual(parsed, [['f', 'x', 'y'], ['Left', 'a', '2'], ['Left', 'b', '3'], ['Right', 'a', '4']]));
      }
      await page.close();
    }
  }
  await check('no browser errors', () => assert.deepEqual(errors, []));
} finally {
  await inputs.close();
  await h.close();
}
if (failures.length) {
  console.error(failures.join('\n'));
  process.exit(1);
}
console.log(`PASS ${cases.length} source-table cases: embedded fields in source order, literal text, booleans, author's precision, CSV quoting, 1,000-row pages and one table per faceted figure`);
